// oracle: gin cleanPath == path.Clean, except it preserves a trailing slash
func wantClean(in string) string {
	if in == "" {
		return "/"
	}
	c := path.Clean(in)
	if !strings.HasPrefix(c, "/") {
		c = "/" + c
	}
	if len(in) > 1 && in[len(in)-1] == '/' && c != "/" {
		c += "/"
	}
	return c
}

